using System.Text;
using Xunit;
using YTDLPHost.Native;
using YTDLPHost.Services;

namespace YTDLPHost.Tests.Native;

/// <summary>
/// Phase 2, step 2.2: a validated request becomes yt-dlp arguments. The golden rows below were generated by running the extension's own
/// command-building code (tools/generate-native-golden.js), so "the host builds what the extension builds today" is checked for real.
/// </summary>
public class DownloadRequestMapperTests
{
    private const string Url = "https://www.youtube.com/watch?v=abcdefghijk";
    private static readonly MapperSettings DefaultFolder = new("");

    public static IEnumerable<object[]> GoldenRows() =>
        GoldenCases.All.Select(c => new object[] { c.Name, c.RequestJson, c.ExpectedCommand });

    private static DownloadRequest Request(string optionsJson, params string[] urls)
    {
        var list = string.Join(",", (urls.Length == 0 ? new[] { Url } : urls).Select(u => $"\"{u}\""));
        return RequestFromJson($"{{\"v\":1,\"id\":\"m1\",\"type\":\"download\",\"urls\":[{list}],\"options\":{{{optionsJson}}}}}");
    }

    private static DownloadRequest RequestFromJson(string wholeJson)
    {
        var parsed = NativeRequestParser.Parse(Encoding.UTF8.GetBytes(wholeJson));
        Assert.True(parsed.Ok, parsed.Error?.Message);
        return (DownloadRequest)parsed.Request!;
    }

    private static MappedDownload MapOne(DownloadRequest request, MapperSettings? settings = null)
    {
        var result = DownloadRequestMapper.Map(request, settings ?? DefaultFolder);
        Assert.True(result.Ok, result.Error);
        return Assert.Single(result.Downloads);
    }

    private static string ValueAfter(MappedDownload download, string flag)
    {
        var args = download.Arguments.ToList();
        return args[args.IndexOf(flag) + 1];
    }

    // ---------------------------------------------------------------- golden: same arguments as the extension builds today

    [Theory]
    [MemberData(nameof(GoldenRows))]
    public void The_arguments_equal_what_the_extension_builds_today(string name, string requestJson, string expectedCommand)
    {
        var download = MapOne(RequestFromJson(requestJson));

        var expected = CommandTokenizer.Tokenize(expectedCommand)!.Skip(1).ToArray();
        Assert.True(expected.SequenceEqual(download.Arguments), $"{name}\nexpected: {string.Join(" | ", expected)}\n     got: {string.Join(" | ", download.Arguments)}");
    }

    [Theory]
    [MemberData(nameof(GoldenRows))]
    public void The_command_string_round_trips_to_the_same_arguments_and_passes_the_validator(string name, string requestJson, string expectedCommand)
    {
        var download = MapOne(RequestFromJson(requestJson));

        var tokens = CommandTokenizer.Tokenize(download.Command)!;
        Assert.Equal("yt-dlp", tokens[0]);
        Assert.True(tokens.Skip(1).SequenceEqual(download.Arguments), name);
        Assert.True(CommandValidator.TryValidate(download.Command, out var reason), reason);
    }

    // ---------------------------------------------------------------- jobs

    [Fact]
    public void Several_urls_become_several_separate_downloads()
    {
        var result = DownloadRequestMapper.Map(Request("\"quality\":\"720\"", "https://a.example/1", "https://a.example/2", "https://a.example/3"), DefaultFolder);

        Assert.True(result.Ok, result.Error);
        Assert.Equal(3, result.Downloads.Count);
        Assert.Equal(new[] { "https://a.example/1", "https://a.example/2", "https://a.example/3" }, result.Downloads.Select(d => d.Arguments[^1]).ToArray());
    }

    [Fact]
    public void A_channel_job_is_one_download_that_carries_every_link()
    {
        var request = Request("\"quality\":\"720\",\"job\":\"channel\",\"archiveName\":\"some_channel\"", "https://a.example/@x", "https://a.example/v/1", "https://a.example/v/2");

        var download = MapOne(request);

        Assert.Equal(new[] { "https://a.example/@x", "https://a.example/v/1", "https://a.example/v/2" }, download.Arguments.TakeLast(3).ToArray());
        Assert.Equal("~/Downloads/YTDownloaderPro/some_channel.archive.txt", ValueAfter(download, "--download-archive"));
    }

    [Fact]
    public void The_cookies_and_user_agent_are_handed_on_untouched()
    {
        var request = RequestFromJson("{\"v\":1,\"id\":\"m1\",\"type\":\"download\",\"urls\":[\"" + Url + "\"],\"options\":{\"quality\":\"1080\"}," +
                              "\"auth\":{\"cookies\":\"# Netscape\\n.x\\tTRUE\",\"userAgent\":\"Mozilla/5.0\"}}");

        var download = MapOne(request);

        Assert.Equal("# Netscape\n.x\tTRUE", download.CookiePayload);
        Assert.Equal("Mozilla/5.0", download.UserAgent);
        Assert.DoesNotContain("Mozilla", download.Command); // the runner decides how to use them, they never become part of the command
    }

    // ---------------------------------------------------------------- the save folder comes from the settings

    [Theory]
    [InlineData("")]
    [InlineData("   ")]
    public void An_empty_folder_setting_means_the_default_folder(string setting)
    {
        var download = MapOne(Request("\"quality\":\"1080\""), new MapperSettings(setting));

        Assert.Equal("~/Downloads/YTDownloaderPro/%(title)s_1080p.mp4", ValueAfter(download, "-o"));
    }

    [Theory]
    [InlineData(@"D:\Videos\My Clips\", "D:/Videos/My Clips/%(title)s_1080p.mp4")]
    [InlineData(@"D:\Videos\\", "D:/Videos/%(title)s_1080p.mp4")]
    [InlineData("D:/Videos", "D:/Videos/%(title)s_1080p.mp4")]
    [InlineData(@"C:\", "C:/%(title)s_1080p.mp4")]
    [InlineData("~/Videos/Mine", "~/Videos/Mine/%(title)s_1080p.mp4")]
    public void A_folder_is_written_with_forward_slashes_and_no_doubled_separators(string setting, string expectedTemplate)
    {
        var download = MapOne(Request("\"quality\":\"1080\""), new MapperSettings(setting));

        Assert.Equal(expectedTemplate, ValueAfter(download, "-o"));
        Assert.Contains("-o \"" + expectedTemplate + "\"", download.Command); // quoted, so a space in the folder is fine
    }

    [Fact]
    public void A_percent_sign_in_the_folder_cannot_become_a_yt_dlp_template_field()
    {
        var download = MapOne(Request("\"quality\":\"1080\""), new MapperSettings(@"E:\100%\clips"));

        Assert.Equal("E:/100%%/clips/%(title)s_1080p.mp4", ValueAfter(download, "-o"));
    }

    [Theory]
    [InlineData("D:\\a\"b")]
    [InlineData("D:\\a\nb")]
    public void A_folder_with_a_quote_or_a_control_character_is_refused(string setting)
    {
        var result = DownloadRequestMapper.Map(Request("\"quality\":\"1080\""), new MapperSettings(setting));

        Assert.False(result.Ok);
        Assert.Contains("cannot be used", result.Error);
    }

    [Fact]
    public void A_folder_the_command_checker_does_not_allow_is_refused_not_passed_on()
    {
        var result = DownloadRequestMapper.Map(Request("\"quality\":\"1080\""), new MapperSettings(@"C:\Windows\System32"));

        Assert.False(result.Ok);
        Assert.Contains("refused by the command checker", result.Error);
    }

    [Fact]
    public void KnownGap_a_unix_folder_is_refused_until_phase_3()
    {
        // CommandValidator only understands "C:\..." and "~" (see its own KnownGap test). When Phase 3 replaces it with
        // allowed-roots validation, flip this to expect success for "/home/me/Videos".
        var result = DownloadRequestMapper.Map(Request("\"quality\":\"1080\""), new MapperSettings("/home/me/Videos"));

        Assert.False(result.Ok);
    }

    // ---------------------------------------------------------------- custom commands

    [Fact]
    public void A_custom_command_gets_the_page_link_appended_and_loses_its_leading_program_name()
    {
        var download = MapOne(Request("\"quality\":\"custom\",\"custom\":\"yt-dlp -f best -o \\\"~/Downloads/YTDownloaderPro/%(title)s.mp4\\\"\""));

        Assert.Equal(new[] { "-f", "best", "-o", "~/Downloads/YTDownloaderPro/%(title)s.mp4", Url }, download.Arguments.ToArray());
    }

    [Fact]
    public void A_custom_command_that_already_has_the_link_is_not_given_it_twice()
    {
        var download = MapOne(Request("\"quality\":\"custom\",\"custom\":\"-f best -o \\\"~/Downloads/YTDownloaderPro/%(title)s.mp4\\\" \\\"" + Url + "\\\"\""));

        Assert.Equal(1, download.Arguments.Count(a => a == Url));
    }

    [Fact]
    public void A_custom_command_still_has_to_pass_the_flag_allowlist()
    {
        var result = DownloadRequestMapper.Map(Request("\"quality\":\"custom\",\"custom\":\"--exec calc\""), DefaultFolder);

        Assert.False(result.Ok);
        Assert.Contains("refused by the command checker", result.Error);
        Assert.Contains("--exec", result.Error);
    }

    [Fact]
    public void A_custom_command_with_an_unclosed_quote_is_refused()
    {
        var result = DownloadRequestMapper.Map(Request("\"quality\":\"custom\",\"custom\":\"-f \\\"best\""), DefaultFolder);

        Assert.False(result.Ok);
        Assert.Contains("unclosed quote", result.Error);
    }

    // ---------------------------------------------------------------- rendering

    [Fact]
    public void Rendering_quotes_the_values_the_extension_quotes_and_anything_with_a_space()
    {
        var command = DownloadRequestMapper.Render(new[] { "-f", "bv*+ba", "-N", "4", "--user-agent", "Mozilla 5.0", "-o", "~/a/%(title)s.mp4", "https://a.example/v" });

        Assert.Equal("yt-dlp -f \"bv*+ba\" -N 4 --user-agent \"Mozilla 5.0\" -o \"~/a/%(title)s.mp4\" \"https://a.example/v\"", command);
    }

    [Fact]
    public void An_argument_with_a_double_quote_cannot_be_rendered()
    {
        Assert.Throws<FormatException>(() => DownloadRequestMapper.Render(new[] { "-o", "a\"b" }));
    }
}
